# How long a key may be. The values that identify a row or a group are kept whole and may take
# 2,704 bytes as the store writes them: a TEXT value takes its bytes and three more, an INTEGER
# nine. One byte more is refused by name and nothing is written. A value in an index has no such
# limit: a row is never refused because a value it indexes is long.

# A key of one TEXT column: 2,701 bytes are 2,704 as written, and 2,702 are one too many.
CREATE TABLE names (name TEXT PRIMARY KEY, n INTEGER);
INSERT INTO names (name, n) VALUES ('', 1);
----
rows affected: 1

INSERT INTO names (name, n) VALUES ('', 2);
----
error: KeyTooLong

INSERT INTO names (name, n) VALUES ('short', 3);
SELECT n FROM names ORDER BY n;
----
n
1
3

# The longest key is found by its value, and a value longer than any key can be finds nothing
# and is no refusal.
SELECT n FROM names WHERE name = '';
----
n
1

SELECT n FROM names WHERE name = '';
----
n

SELECT n FROM names WHERE name = '';
----
n

# An UPDATE that would make the key too long is refused and leaves the row.
UPDATE names SET name = '' WHERE n = 3;
----
error: KeyTooLong

SELECT name FROM names WHERE n = 3;
----
name
short

# A key of two columns is measured as a whole: a TEXT of 2,692 bytes and an INTEGER are 2,704.
CREATE TABLE pairs (label TEXT NOT NULL, seq INTEGER NOT NULL, n INTEGER, PRIMARY KEY (label, seq));
INSERT INTO pairs (label, seq, n) VALUES ('', 1, 1);
----
rows affected: 1

INSERT INTO pairs (label, seq, n) VALUES ('', 1, 2);
----
error: KeyTooLong

SELECT n FROM pairs ORDER BY n;
----
n
1

# The values of a kept count name a group and are held to the same limit.
CREATE TABLE tagged (id INTEGER PRIMARY KEY, tag TEXT NOT NULL);
CREATE INDEX tagged_tag ON tagged (tag);
ALTER TABLE tagged SET MAINTAIN COUNT (tag);
INSERT INTO tagged (id, tag) VALUES (1, '');
----
rows affected: 1

INSERT INTO tagged (id, tag) VALUES (2, '');
----
error: KeyTooLong

UPDATE tagged SET tag = '' WHERE id = 1;
----
error: KeyTooLong

SELECT COUNT(*) AS n FROM tagged WHERE tag = '';
----
n
1

SELECT id FROM tagged ORDER BY id;
----
id
1

# The values of a PARTITION_KEY name a partition and are held to it as well, for a row that has
# a vector.
CREATE TABLE shapes (id INTEGER PRIMARY KEY, family TEXT NOT NULL, v VECTOR(2) PARTITION_KEY (family));
INSERT INTO shapes (id, family, v) VALUES (1, '', [1.0, 0.0]);
----
rows affected: 1

INSERT INTO shapes (id, family, v) VALUES (2, '', [0.0, 1.0]);
----
error: KeyTooLong

SELECT id FROM shapes ORDER BY id;
----
id
1

# The same values in a plain index, in a UNIQUE rule and beside a key are stored: 2,702 bytes,
# and 5,000.
CREATE TABLE notes (id INTEGER PRIMARY KEY, body TEXT, title TEXT UNIQUE);
CREATE INDEX notes_body ON notes (body);
INSERT INTO notes (id, body, title) VALUES (1, '', '');
----
rows affected: 1

INSERT INTO notes (id, body, title) VALUES (2, '', '');
----
rows affected: 1

UPDATE notes SET body = '' WHERE id = 1;
----
rows affected: 1

SELECT id FROM notes WHERE body = '';
----
id
2

SELECT id FROM notes WHERE title = '';
----
id
1

# The UNIQUE rule still holds over the long value.
INSERT INTO notes (id, body, title) VALUES (3, 'short', '');
----
error: UniqueViolation

SELECT id FROM notes ORDER BY id;
----
id
1
2

# Texts of 300 bytes, between the 256 an index entry keeps and the key limit, that differ only at
# byte 280. Each is found by its own value, a UNIQUE rule takes all six and refuses a repeat,
# a range and an ORDER BY give them in the order of their values, and COUNT(*) counts the rows
# that hold one of them. Inserted out of order, so the order of the ids is not the order sought.
CREATE TABLE mid (id INTEGER PRIMARY KEY, t TEXT UNIQUE, u TEXT);
CREATE INDEX mid_u ON mid (u);
INSERT INTO mid (id, t, u) VALUES (1, '', ''), (2, '', ''), (3, '', ''), (4, '', ''), (5, '', ''), (6, '', '');
----
rows affected: 6

SELECT id FROM mid WHERE t = '';
----
id
2

INSERT INTO mid (id, t, u) VALUES (8, '', 'other');
----
error: UniqueViolation

INSERT INTO mid (id, t, u) VALUES (7, 'p', '');
----
rows affected: 1

SELECT COUNT(*) FROM mid WHERE u = '';
----
COUNT
2

SELECT COUNT(*) FROM mid WHERE u = '';
----
COUNT
1

SELECT id FROM mid WHERE t > '' ORDER BY id;
----
id
3
5
6

SELECT id FROM mid WHERE t <= '' ORDER BY id;
----
id
1
2
4
7

SELECT id FROM mid ORDER BY t LIMIT 7;
----
id
7
2
4
1
6
5
3

SELECT id FROM mid ORDER BY t DESC LIMIT 4;
----
id
3
5
6
1
